                }, { immediate: true });

                onMounted(fetchData);

                return {
                    loading, error, showSettings, fontSize, theme, expandedSections,
                    characters,
                    SafeGetValue, toggleSection,
                };
            }
        };

        setTimeout(() => {
            try {
                createApp(App).mount('#app');
            } catch(e) {
                document.body.innerHTML = `<div class="text-center p-10 text-lg"><i class="fa fa-warning mr-2"></i> <span class="text-red-400">Vue 应用初始化失败... 珠玑也无能为力了, 主人检查下环境配置吧?</span></div>`
                console.error("Vue mounting error:", e)
            }
        }, 100);
    </script>
</body>
</html>
```

